 v_target jsonb; v_oid oid; v_args text; v_call text; v_role text;
 v_denials integer; v_total integer:=0; v_counts jsonb:='{}'::jsonb;
 v_checks jsonb:='{}'::jsonb; v_value text; v_factor numeric; v_family jsonb; v_dates integer;
begin
 if not exists(select 1 from mushavo_email_install.rollout_control
  where singleton and target_project='dczlddwbtgvfdujgcitb' and mode='ACTIVE'
   and catalog_sha256=mushavo_email_install.catalog_identity()) then
  raise exception 'CURRENT_STAGING_CATALOG_REQUIRED';
 end if;
 if jsonb_array_length(v_targets)<>100 then raise exception 'EXACT_FROZEN_MATRIX_REQUIRED'; end if;
 for v_target in select value from jsonb_array_elements(v_targets) loop
  select p.oid into strict v_oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname=v_target->>'schema' and p.proname=v_target->>'name'
    and pg_get_function_identity_arguments(p.oid)=v_target->>'identity_arguments';
  if md5(pg_get_functiondef(v_oid)) is distinct from v_target->>'definition_md5'
    or has_function_privilege('anon',v_oid,'EXECUTE')
    or has_function_privilege('authenticated',v_oid,'EXECUTE')
    or not has_function_privilege('service_role',v_oid,'EXECUTE') then
   raise exception 'FROZEN_DEFINITION_OR_GRANT_MISMATCH';
  end if;
  v_total:=v_total+1;
 end loop;
 v_checks:=jsonb_build_object('frozen_definitions_and_grants_match',v_total=100);
 foreach v_role in array array['anon','authenticated'] loop
  v_denials:=0;
  for v_target in select value from jsonb_array_elements(v_targets) loop
   select p.oid into strict v_oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname=v_target->>'schema' and p.proname=v_target->>'name'
     and pg_get_function_identity_arguments(p.oid)=v_target->>'identity_arguments';
   select coalesce(string_agg('null::'||format_type(a.type_oid,null),',' order by a.ordinality),'') into v_args
    from pg_proc p cross join lateral unnest(p.proargtypes::oid[]) with ordinality a(type_oid,ordinality)
    where p.oid=v_oid;
   v_call:=format('select %I.%I(%s)',v_target->>'schema',v_target->>'name',v_args);
   perform set_config('request.jwt.claims',jsonb_build_object('role',v_role)::text,true);
   execute format('set local role %I',v_role);
   begin
    execute v_call;
    raise exception 'UNEXPECTED_SERVICE_ONLY_EXECUTE_SUCCEEDED';
   exception when insufficient_privilege then
    v_denials:=v_denials+1;
   end;
   execute 'reset role';
  end loop;
  if v_denials<>100 then raise exception 'INCOMPLETE_ROLE_DENIALS'; end if;
  v_counts:=v_counts||jsonb_build_object(v_role,v_denials);
 end loop;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 execute 'set local role service_role';
 select public.business_report_csv_cell('=1+1',false) into v_value;
 v_checks:=v_checks||jsonb_build_object('service_CSV_formula_escape',v_value=('"'||chr(39)||'=1+1"'));
 select public.business_seat_proration('2026-01-01T00:00:00Z','2026-01-31T00:00:00Z','2026-01-16T00:00:00Z') into v_factor;
 v_checks:=v_checks||jsonb_build_object('service_Business_half_term_proration',v_factor=0.5);
 select public.family_extra_place_proration('2026-05-20T00:00:00Z','2027-05-20T00:00:00Z','2026-06-10T00:00:00Z') into v_family;
 v_checks:=v_checks||jsonb_build_object('service_Family_latter_half_eleven_full_months',
   (v_family->>'factor')::numeric=11 and (v_family->>'full_months_remaining')::integer=11 and v_family->>'current_half_charge'='false');
 select count(*) into v_dates from public.currency_conversion_backfill_dates(0);
 v_checks:=v_checks||jsonb_build_object('service_FX_read_only_zero_limit',v_dates=0);
 execute 'reset role';
 if exists(select 1 from jsonb_each(v_checks) where value is distinct from 'true'::jsonb) then
  raise exception 'READ_ONLY_MATRIX_POSITIVE_ASSERTION_FAILED';
 end if;
 perform set_config('mushavo.batch_y.matrix_result',jsonb_build_object(
  'project','dczlddwbtgvfdujgcitb','checked_at',clock_timestamp(),
  'transaction_read_only',current_setting('transaction_read_only'),
  'signatures',v_total,'actual_role_execute_denials',v_counts,'checks',v_checks,
  'ordinary_HTTP_login',false,'role_claims_modeled',true,
  'permitted_service_read_only_calls',4,'committed_writes',0,
  'provider_requests',0,'emails',0,'pushes',0,'exit_code',0)::text,true);
end;
$audit$;
select current_setting('mushavo.batch_y.matrix_result')::jsonb as safe_result;
rollback;
